import "sync"

// ProcessAll applies fn to each integer in jobs and returns the results
// in the original input order. It processes jobs in parallel using workers
// goroutines. If workers <= 0, it uses one worker.
func ProcessAll(jobs []int, workers int, fn func(int) int) []int {
	if workers <= 0 {
		workers = 1
	}
	if workers > len(jobs) {
		workers = len(jobs)
	}

	results := make([]int, len(jobs))
	if len(jobs) == 0 {
		return results
	}

	indices := make(chan int)
	var wg sync.WaitGroup
	wg.Add(workers)

	for i := 0; i < workers; i++ {
