/**
 * Groups the elements of an array based on the return value of a key function.
 *
 * @param {Array} arr - The array to group.
 * @param {Function} keyFn - Function that returns the grouping key for each item.
 * @returns {Object} An object of the form { key: [items...] }.
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError('groupBy: first argument must be an array');
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError('groupBy: second argument must be a function');
  }

  const result = Object.create(null);

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);

    // Coerce key to string so it can be used as an object property.
    const keyStr = String(key);

    if (!Object.prototype.hasOwnProperty.call(result, keyStr)) {
      result[keyStr] = [];
    }
    result[keyStr].push(item);
  }

  return result;
}

module.exports = { groupBy };
