'use strict';

/**
 * A tiny synchronous event emitter.
 *
 * Semantics (modelled on Node's EventEmitter):
 *  - handlers run in registration order;
 *  - `emit` iterates a *snapshot*, so subscribing/unsubscribing from inside a
 *    handler never corrupts the iteration;
 *  - a `once` handler is unregistered *before* it is invoked, and is flagged as
 *    "fired" so that a re-entrant `emit` can never run it a second time;
 *  - `off(event, fn)` removes one instance of `fn` (register twice -> remove twice);
 *  - `off(event)` removes every handler for that event.
 */
class Emitter {
  constructor() {
    // event -> array of { fn, once, fired }
    this._events = new Map();
  }

  /** Subscribe. Returns `this` for chaining. */
  on(event, fn) {
    return this._add(event, fn, false);
  }

  /** Subscribe for a single invocation. Returns `this` for chaining. */
  once(event, fn) {
    return this._add(event, fn, true);
  }

  _add(event, fn, once) {
    if (typeof fn !== 'function') {
      throw new TypeError('listener must be a function');
    }
    let list = this._events.get(event);
    if (!list) {
      list = [];
      this._events.set(event, list);
    }
    list.push({ fn, once, fired: false });
    return this;
  }

  /**
   * Unsubscribe. With `fn`, removes the first matching handler (works for
   * handlers registered with `once` too). Without `fn`, removes them all.
   * Returns `this` for chaining.
   */
  off(event, fn) {
    const list = this._events.get(event);
    if (!list) return this;

    if (fn === undefined) {
      this._events.delete(event);
      return this;
    }

    const i = list.findIndex((entry) => entry.fn === fn);
    if (i !== -1) list.splice(i, 1);
    if (list.length === 0) this._events.delete(event);
    return this;
  }

  /**
   * Invoke every handler for `event` in registration order.
   * Returns the number of handlers that were invoked.
   */
  emit(event, ...args) {
    const list = this._events.get(event);
    if (!list || list.length === 0) return 0;

    // Snapshot: mutations during dispatch can't break this loop.
    const snapshot = list.slice();
    let called = 0;

    for (const entry of snapshot) {
      // Already consumed by a re-entrant emit? Skip it.
      if (entry.fired) continue;

      if (entry.once) {
        entry.fired = true; // mark + unregister BEFORE running
        const live = this._events.get(event);
        if (live) {
          const i = live.indexOf(entry);
          if (i !== -1) live.splice(i, 1);
          if (live.length === 0) this._events.delete(event);
        }
      }

      called++;
      entry.fn.apply(this, args);
    }

    return called;
  }

  /** Number of handlers currently registered for `event`. */
  listenerCount(event) {
    const list = this._events.get(event);
    return list ? list.length : 0;
  }

  /** The raw functions currently registered for `event`. */
  listeners(event) {
    const list = this._events.get(event);
    return list ? list.map((entry) => entry.fn) : [];
