import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock=None):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock if clock is not None else time.monotonic
        # key -> (value, expiry_time), ordered by recency of use (LRU first)
        self._data = OrderedDict()

    def _is_expired(self, expiry, now):
        return now >= expiry

    def get(self, key):
        if key not in self._data:
            return None
        now = self.clock()
        value, expiry = self._data[key]
        if self._is_expired(expiry, now):
            # Expired: remove and treat as missing.
            del self._data[key]
            return None
        # Count as a use: move to most-recently-used position.
        self._data.move_to_end(key)
        return value

    def put(self, key, value):
        now = self.clock()
        expiry = now + self.ttl
        if key in self._data:
            # Update value/expiry and mark as most recently used.
            self._data[key] = (value, expiry)
            self._data.move_to_end(key)
            return

        self._data[key] = (value, expiry)
        self._data.move_to_end(key)

        # Evict if over capacity.
        if len(self._data) > self.capacity:
            self._evict(now)

    def _evict(self, now):
        # Prefer evicting an expired entry (scan from LRU side); otherwise
        # evict the true LRU entry.
        for k, (_, expiry) in list(self._data.items()):
            if self._is_expired(expiry, now):
                del self._data[k]
                if len(self._data) <= self.capacity:
                    return
        # Still over capacity: evict least-recently-used (front of OrderedDict).
        while len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        now = self.clock()
        # Clean up expired entries so length reflects valid entries only.
        expired = [k for k, (_, expiry) in self._data.items()
                   if self._is_expired(expiry, now)]
        for k in expired:
            del self._data[k]
        return len(self._data)
