from typing import Dict, List, Any


def _parse_status(token: str):
    """Return the status code as int, or None if it is not a valid integer."""
    try:
        return int(token)
    except (TypeError, ValueError):
        return None


def _parse_duration(token: str):
    """Return the response time in ms as float, or None if it is not numeric.

    Accepts values like '34ms' as well as plain '34' / '34.5'.
    """
    if token is None:
        return None
    value = token[:-2] if token.endswith("ms") else token
    try:
        return float(value)
    except ValueError:
        return None


def summarize(lines: List[str]) -> Dict[str, Any]:
    total = 0
    by_status: Dict[int, int] = {}
    errors = 0
    # path -> [sum_of_times, count]
    path_times: Dict[str, List[float]] = {}

    for line in lines:
        if not isinstance(line, str):
            continue

        parts = line.split()
        if len(parts) < 5:
            continue

        _timestamp, _method, path, status_tok, time_tok = parts[:5]

        status = _parse_status(status_tok)
        if status is None:
            continue

        duration = _parse_duration(time_tok)
        if duration is None:
            continue

        total += 1
        by_status[status] = by_status.get(status, 0) + 1
        if 500 <= status <= 599:
            errors += 1

        bucket = path_times.setdefault(path, [0.0, 0])
        bucket[0] += duration
        bucket[1] += 1

    if path_times:
        # Highest average response time; ties broken by lexicographically first path.
        slowest_path = min(
            path_times.items(),
            key=lambda item: (-(item[1][0] / item[1][1]), item[0]),
        )[0]
    else:
        slowest_path = None

    error_rate = round(errors / total, 4) if total else 0.0

    return {
        "total": total,
        "by_status": by_status,
        "slowest_path": slowest_path,
        "error_rate": error_rate,
    }


if __name__ == "__main__":
