package main

import (
	"fmt"
	"sync"
)

// MapConcurrent applies f to each element of in, running at most `limit`
// calls concurrently. The returned slice preserves input order.
func MapConcurrent(in []int, limit int, f func(int) int) []int {
	if limit <= 0 {
		limit = 1
	}

	out := make([]int, len(in))
	sem := make(chan struct{}, limit)
	var wg sync.WaitGroup

	for i, v := range in {
		wg.Add(1)
		sem <- struct{}{} // acquire a slot
		go func(idx, val int) {
			defer wg.Done()
			defer func() { <-sem }() // release the slot
			out[idx] = f(val)
		}(i, v)
	}

	wg.Wait()
	return out
}

func main() {
	in := []int{1, 2, 3, 4, 5}
	out := MapConcurrent(in, 2, func(x int) int {
		return x * x
	})
	fmt.Println(out)
}
