import (
	"fmt"
	"sync"
	"time"
)

// MapConcurrent applies f to every element of in, running at most `limit`
// calls of f concurrently. A limit <= 0 is treated as 1.
//
// The returned slice has the same length as in and preserves input order:
// out[i] == f(in[i]).
func MapConcurrent(in []int, limit int, f func(int) int) []int {
	if len(in) == 0 {
		return []int{}
	}
	if limit <= 0 {
		limit = 1
	}
