'use strict';

/**
 * Format an integer number of minor units (cents) as a USD display string.
 *
 *   formatUSD(1234567) // "$12,345.67"
 *   formatUSD(-5000)   // "-$50.00"
 *   formatUSD(0)       // "$0.00"
 *
 * @param {number} minorUnits Integer count of cents.
 * @returns {string}
 * @throws {TypeError} If `minorUnits` is not an integer Number.
 */
function formatUSD(minorUnits) {
  // Reject strings, booleans, null/undefined, objects, BigInt, NaN,
  // Infinity, and non-integral numbers such as 1.5.
  if (typeof minorUnits !== 'number' || !Number.isInteger(minorUnits)) {
    throw new TypeError(
      `formatUSD expects an integer number of minor units, received: ${String(minorUnits)}`
    );
  }

  // `-0 < 0` is false, so negative zero formats as "$0.00" rather than "-$0.00".
  const isNegative = minorUnits < 0;
  const abs = Math.abs(minorUnits);

  const dollars = Math.floor(abs / 100);
  const cents = abs % 100;

  // Insert a comma at every position that is preceded by a digit and
  // followed by a multiple of three digits.
  const groupedDollars = String(dollars).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  const paddedCents = String(cents).padStart(2, '0');

  return `${isNegative ? '-' : ''}$${groupedDollars}.${paddedCents}`;
}

module.exports = { formatUSD };
