/**
 * Cursor-based pagination over an id-ascending array.
 *
 * @param {Array<{id: *}>} rows   Rows sorted ascending by `id`.
 * @param {*} cursor              `null`/`undefined` to start at the beginning,
 *                                otherwise the id to start *after*.
 * @param {number} size           Max number of items to return (>= 1).
 * @returns {{items: Array, nextCursor: *}}
 * @throws {RangeError} when `size` is not a number >= 1.
 */
function page(rows, cursor, size) {
  if (typeof size !== 'number' || !Number.isFinite(size) || size < 1) {
    throw new RangeError('size must be a number >= 1');
  }

  const list = Array.isArray(rows) ? rows : [];
  const limit = Math.floor(size);

  let start = 0;

  if (cursor !== null && cursor !== undefined) {
    const idx = indexOfId(list, cursor);
    if (idx === -1) {
      // Unknown cursor: nothing to page over.
      return { items: [], nextCursor: null };
    }
    start = idx + 1;
  }

  const items = list.slice(start, start + limit);
  const hasMore = start + items.length < list.length;
  const nextCursor = hasMore && items.length > 0 ? items[items.length - 1].id : null;

  return { items, nextCursor };
}

/**
 * Binary search for a row id (rows are sorted ascending); falls back to a
 * linear scan if the ids are not comparable with `<` / `>`.
 */
function indexOfId(list, id) {
  let lo = 0;
  let hi = list.length - 1;

  while (lo <= hi) {
    const mid = (lo + hi) >>> 1;
    const midId = list[mid].id;

    if (midId === id) return mid;
    if (midId < id) lo = mid + 1;
    else if (midId > id) hi = mid - 1;
    else break; // incomparable (e.g. NaN / mixed types) -> linear scan
  }

  for (let i = 0; i < list.length; i++) {
    if (list[i].id === id) return i;
  }
  return -1;
}

module.exports = { page };
