 *  - A key explicitly set to `undefined` still counts as present, so
 *    `{ a: undefined }` vs `{}` yields a removal, not a no-op.
 *
 * @param {Object} before
 * @param {Object} after
 * @returns {{added: Object, removed: Object, changed: Object}}
 */
function diff(before, after) {
  const a = before == null ? {} : before;
  const b = after == null ? {} : after;

  const has = (obj, key) => Object.prototype.hasOwnProperty.call(obj, key);

  const added = {};
  const removed = {};
  const changed = {};

  for (const key of Object.keys(a)) {
    if (!has(b, key)) {
      removed[key] = a[key];
    } else if (a[key] !== b[key]) {
      changed[key] = [a[key], b[key]];
    }
  }

  for (const key of Object.keys(b)) {
    if (!has(a, key)) {
      added[key] = b[key];
    }
  }

  return { added, removed, changed };
