import re
from typing import Dict, List


# --------------------------------------------------------------------------- #
#  Normalisation helpers
# --------------------------------------------------------------------------- #
def _norm_email(value: str) -> str:
    """Surrounding whitespace ignored, compared case-insensitively."""
    return (value or "").strip().lower()


def _norm_phone(value: str) -> str:
    """
    Reduce a phone number to its canonical digits-only local form.

        '010-1234-5678'      -> '01012345678'
        '01012345678'        -> '01012345678'
        '+82 10 1234 5678'   -> '01012345678'
        '0082-10-1234-5678'  -> '01012345678'
    """
    digits = re.sub(r"\D", "", value or "")
    if not digits:
        return ""

    # international dialling prefix written as 00...
    if digits.startswith("00"):
        digits = digits[2:]

    # country code 82 -> drop it and restore the leading 0
    if digits.startswith("82") and len(digits) > 2:
        rest = digits[2:]
        digits = rest if rest.startswith("0") else "0" + rest

    return digits


def _orders_of(row: dict) -> int:
    try:
        return int(row.get("orders") or 0)
    except (TypeError, ValueError):
        return 0


# --------------------------------------------------------------------------- #
#  Main entry point
# --------------------------------------------------------------------------- #
def merge_customers(rows: List[dict]) -> List[dict]:
    """
    Collapse duplicate customer records.

    Two records belong to the same customer when
      1. their emails match (case-insensitive, trimmed), or
      2. their phone numbers match (digits only, country code 82 normalised).
    A shared name alone never merges records.

    Matching is transitive: A~B by email and B~C by phone puts A, B and C
    into one customer.  The result preserves first-appearance order.
    """
    n = len(rows)
    if n == 0:
        return []

    # ---------------- union-find over record indices ----------------------- #
    parent = list(range(n))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path compression
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra != rb:
            # keep the earlier index as the representative
            if rb < ra:
                ra, rb = rb, ra
            parent[rb] = ra

    email_owner: Dict[str, int] = {}
    phone_owner: Dict[str, int] = {}

    norm = []
    for i, row in enumerate(rows):
        email = _norm_email(row.get("email", ""))
        phone = _norm_phone(row.get("phone", ""))
        norm.append((email, phone))

        if email:
            if email in email_owner:
                union(email_owner[email], i)
            else:
                email_owner[email] = i
        if phone:
            if phone in phone_owner:
                union(phone_owner[phone], i)
            else:
                phone_owner[phone] = i

    # unions may have changed representatives; re-point the key maps
    for table in (email_owner, phone_owner):
        for key, idx in table.items():
            table[key] = find(idx)

    # ---------------- aggregate each group in input order ------------------ #
    merged: Dict[int, dict] = {}
    order: List[int] = []

    for i, row in enumerate(rows):
        root = find(i)
        email, phone = norm[i]
        name = (row.get("name") or "").strip()
        orders = _orders_of(row)

        if root not in merged:
            merged[root] = {
                "name": name,
                "email": email,
                "phone": phone,
                "orders": orders,
            }
            order.append(root)
            continue

        cur = merged[root]
        # name: longer wins, ties go to the earlier record
        if len(name) > len(cur["name"]):
            cur["name"] = name
        # email / phone: first non-empty value wins
        if not cur["email"] and email:
            cur["email"] = email
        if not cur["phone"] and phone:
            cur["phone"] = phone
        # orders: sum
        cur["orders"] += orders

    return [merged[root] for root in order]


# --------------------------------------------------------------------------- #
if __name__ == "__main__":
    data = [
        {"name": "Kim",        "email": "KIM@Example.com ", "phone": "",                  "orders": 2},
        {"name": "Kim Cheolsu","email": "kim@example.com",  "phone": "010-1234-5678",     "orders": 3},
        {"name": "CS Kim",     "email": "",                 "phone": "+82 10 1234 5678",  "orders": 1},
        {"name": "Lee",        "email": "lee@example.com",  "phone": "01099998888",       "orders": 5},
        {"name": "Lee",        "email": "",                 "phone": "",                  "orders": 7},
    ]
    for r in merge_customers(data):
        print(r)
    # {'name': 'Kim Cheolsu', 'email': 'kim@example.com', 'phone': '01012345678', 'orders': 6}
    # {'name': 'Lee', 'email': 'lee@example.com', 'phone': '01099998888', 'orders': 5}
    # {'name': 'Lee', 'email': '', 'phone': '', 'orders': 7}
