def first_free(busy, duration, day_start=9 * 60, day_end=18 * 60):
    if duration < 0:
        raise ValueError("duration must be non-negative")
    if day_start > day_end:
        raise ValueError("day_start must not exceed day_end")

    intervals = sorted(
        (max(start, day_start), min(end, day_end))
        for start, end in busy
        if start < end and end > day_start and start < day_end
    )

    cursor = day_start

    for start, end in intervals:
        if start - cursor >= duration:
            return cursor
        cursor = max(cursor, end)

    return cursor if day_end - cursor >= duration else None
